 receipt.pendingMatrix=[];for(const c of matrix('full')){const o=await context(c);await signIn(o.p,'negative');let ready=true;try{await o.p.getByRole('button',{name:c.lang==='en'?'They match':'指紋相符',exact:true}).waitFor({timeout:4000});}catch{ready=false;await shot(o.p,`A8-09-pending-load-error-${caseName(c)}`);const retry=o.p.getByRole('button',{name:c.lang==='en'?'Try again':'重試',exact:true});if(await retry.count()){await retry.first().click();receipt.clicks.push('Retry pending welcome '+caseName(c));try{await o.p.getByRole('button',{name:c.lang==='en'?'They match':'指紋相符',exact:true}).waitFor({timeout:5000});ready=true;}catch{}}}receipt.pendingMatrix.push({case:caseName(c),ready});await shot(o.p,`A8-09-pending-${caseName(c)}`);await geometry(o.p,caseName(c)+' pending');await o.ctx.close();}
